using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Windows.Forms;
public sealed partial class GuntBar {
 DateTime nextAutomation=DateTime.MinValue;int automationBusy;readonly Dictionary<string,string> observedTriggers=new Dictionary<string,string>();string registeredDeveloperKey;
 void LaunchDeveloperWindow(string page){string exe=Path.Combine(root,"bin","GUNT.ControlCenter.exe");if(!File.Exists(exe)){Log("developer-unavailable","제어 센터 실행 파일이 없습니다.");return;}Process.Start(new ProcessStartInfo(exe,"\""+root+"\" "+page){UseShellExecute=false,CreateNoWindow=true});}
 [System.Runtime.InteropServices.DllImport("user32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]static extern IntPtr FindWindow(string c,string title);
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool PostMessage(IntPtr hwnd,uint message,IntPtr w,IntPtr l);
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool ShowWindow(IntPtr hwnd,int state);
 DateTime launchpadConfigTime=DateTime.MinValue;string registeredLaunchpadKey;bool launchpadConfigured;
 void ToggleLaunchpad(){var foreground=GetForegroundWindow();var h=GuntLaunchpadWindow.Find(root);if(h!=IntPtr.Zero){if(IsWindowVisible(h)){PostMessage(h,0x8006,IntPtr.Zero,foreground);}else{ShowWindow(h,5);SetForegroundWindow(h);PostMessage(h,0x8006,new IntPtr(1),foreground);}return;}LaunchDeveloperWindow("launchpad");}
 void ConfigureLaunchpadHotkey(){string path=Path.Combine(root,"config","launchpad.json");DateTime stamp=File.Exists(path)?File.GetLastWriteTimeUtc(path):DateTime.MinValue;if(launchpadConfigured&&stamp==launchpadConfigTime)return;launchpadConfigured=true;launchpadConfigTime=stamp;try{string key="Ctrl+Alt+L";bool enabled=true;if(File.Exists(path)){var c=Read("config/launchpad.json");key=Str(c,"Shortcut",key);enabled=Flag(c,"HotkeyEnabled",true);}if(registeredLaunchpadKey!=key||!enabled){UnregisterHotKey(Handle,27);registeredLaunchpadKey=null;}uint modifiers,code;bool valid=GuntLaunchpadHotkey.TryParse(key,out modifiers,out code);bool available=enabled&&valid&&(registeredLaunchpadKey==key||RegisterHotKey(Handle,27,modifiers,code));if(available)registeredLaunchpadKey=key;string status=!enabled?"사용 안 함":available?key+" 등록됨":"등록 불가 · 다른 프로그램의 단축키를 확인하세요.";GuntConfiguration.Atomic(root,Path.Combine(root,"state","launchpad-hotkey.json"),json.Serialize(new{Shortcut=key,Available=available,Status=status}),false);}catch(Exception e){Log("launchpad-hotkey-error",e.Message);}}
 void ConfigureDeveloperHotkey(){UnregisterHotKey(Handle,26);string key="Ctrl+Alt+Space";try{string file=Path.Combine(root,"config","ux.json");if(File.Exists(file))key=Str(Read("config/ux.json"),"globalPaletteShortcut",key);uint modifiers=key=="Ctrl+Shift+Space"?0x4006u:0x4003u;bool valid=key=="Ctrl+Alt+Space"||key=="Ctrl+Shift+Space";bool registered=valid&&RegisterHotKey(Handle,26,modifiers,0x20);registeredDeveloperKey=registered?key:null;string status=key=="Disabled"?"사용 안 함":registered?key+" 등록됨":"등록 불가 · 기존 단축키 보존";GuntConfiguration.Atomic(root,Path.Combine(root,"state","developer-hotkey.json"),json.Serialize(new{Shortcut=key,Available=registered,Status=status}),false);if(valid&&!registered)Log("developer-hotkey-unavailable",status);}catch(Exception e){Log("developer-hotkey-error",e.Message);}}
 void PollDeveloperAutomation(){if(DateTime.UtcNow<nextAutomation||Interlocked.CompareExchange(ref automationBusy,1,0)!=0)return;nextAutomation=DateTime.UtcNow.AddSeconds(10);ThreadPool.QueueUserWorkItem(delegate{try{string file=Path.Combine(root,"config","smart-automation.json");if(!File.Exists(file))return;var config=Read("config/smart-automation.json");if(!config.ContainsKey("Rules"))return;var rules=new List<Dictionary<string,object>>();foreach(var item in (IEnumerable)config["Rules"]){var rule=item as Dictionary<string,object>;if(rule!=null&&Flag(rule,"Enabled",false))rules.Add(rule);}rules.Sort((a,b)=>Num(b,"Priority",50).CompareTo(Num(a,"Priority",50)));foreach(var rule in rules){string trigger=Str(rule,"Trigger",""),id=Str(rule,"Id",""),value=null;if(!System.Text.RegularExpressions.Regex.IsMatch(id,@"^[a-zA-Z0-9_-]{1,80}$"))continue;if(trigger=="application-running"){string app=Str(rule,"TriggerValue","");if(!System.Text.RegularExpressions.Regex.IsMatch(app,@"^[\p{L}\p{N}_.-]{1,80}$"))continue;var processes=Process.GetProcessesByName(app.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)?app.Substring(0,app.Length-4):app);value=processes.Length>0?"running":"stopped";foreach(var process in processes)process.Dispose();}else if(trigger=="ac-connected"||trigger=="battery")value=SystemInformation.PowerStatus.PowerLineStatus.ToString();else if(trigger=="monitor-changed")value=String.Join("|",Screen.AllScreens.Select(s=>s.DeviceName+":"+s.Bounds.ToString()+":"+GuntLayout.Scale(s)));else continue;string prior;bool exists=observedTriggers.TryGetValue(id,out prior);observedTriggers[id]=value;bool edge=trigger=="application-running"?value=="running"&&(!exists||prior!=value):exists&&prior!=value;if(!edge)continue;string exe=Path.Combine(root,"bin","GUNT.ControlCenter.exe");using(var worker=Process.Start(new ProcessStartInfo(exe,"\""+root+"\" automation-event "+id){UseShellExecute=false,CreateNoWindow=true})){if(!worker.WaitForExit(60000))Log("automation-pending","자동화 작업이 아직 처리 중입니다. 중복 작업은 서비스에서 제한합니다.");}}}catch(Exception e){Log("automation-error",e.Message);}finally{Interlocked.Exchange(ref automationBusy,0);}});}
}
